import {Tabs} from '@jetbrains/ring-ui-built/components/tabs/tabs'
import {HTTPCodesEnum, HTTPError} from '@jetbrains/teamcity-ui/dist/services'
import {objectToQuery} from '@jetbrains/teamcity-ui/dist/utils'
import * as React from 'react'
import {Suspense} from 'react'
import type {EntryPointProps} from 'react-relay'
import {EntryPointContainer, graphql, useFragment, usePreloadedQuery} from 'react-relay'
import type {PreloadedEntryPoint} from 'react-relay/relay-hooks/EntryPointTypes'
import {useLocation, useNavigate, useParams} from 'react-router'

import AgentHistory from '../../../../containers/AgentHistory'
import {useQueryParam} from '../../../../hooks/routes'
import {getTabsArg} from '../../../../rest/tabs'
import {getAgentTypeHref, getHrefWithQueryParams} from '../../../../routes'
import {restApi} from '../../../../services/rest'
import {
  ClassicUICloudImageTabNamesEnum,
  OverviewCloudImageTabNamesEnum,
  stringifyId,
  toAgentTypeId,
  toTabId,
} from '../../../../types'
import type {AgentTypeId} from '../../../../types'
import {emptyArray} from '../../../../utils/empty'
import {getAvailabilityErrorMessage} from '../../../../utils/getAvailabilityErrorMessage'
import {getTabParamsKey} from '../../../../utils/tabs'
import ClassicUITabAdapter from '../../../common/ClassicUITabAdapter/ClassicUITabAdapter'
import Loader from '../../../common/Loader/Loader'
import OverviewTab from '../../../common/OverviewTab/OverviewTab'
import tabStyles from '../../../common/OverviewTab/OverviewTab.module.css'
import PageTitle from '../../../common/PageTitle/PageTitle'

import type {AgentTypePage_agentType$key} from './__generated__/AgentTypePage_agentType.graphql'
import type {AgentTypePage_cloudImages$key} from './__generated__/AgentTypePage_cloudImages.graphql'
import type {AgentTypePageQuery} from './__generated__/AgentTypePageQuery.graphql'
import {query} from './AgentTypePage.queries'
import type {AgentTypeParametersComponentType} from './AgentTypeParameters/AgentTypeParameters'
import type {AgentTypeParametersEntryPoint} from './AgentTypeParameters/AgentTypeParameters.entryPoint'
import CloudProfileError from './CloudProfileError/CloudProfileError'

import styles from './AgentTypePage.module.css'

const IFRAME_TABS = [
  OverviewCloudImageTabNamesEnum.SUMMARY,
  OverviewCloudImageTabNamesEnum.HISTORY,
  OverviewCloudImageTabNamesEnum.COMPATIBLE_CONFIGUTATIONS,
  OverviewCloudImageTabNamesEnum.BUILD_RUNNERS,
  OverviewCloudImageTabNamesEnum.AGENT_PARAMETERS,
]

const agentTypeFragment = graphql`
  fragment AgentTypePage_agentType on AgentTypeRest {
    name
  }
`

const cloudImagesFragment = graphql`
  fragment AgentTypePage_cloudImages on CloudImages {
    cloudImage {
      profile {
        id
        project {
          id
        }
        error {
          message
          detailedMessage
        }
      }
    }
  }
`

type Props = {
  agentTypeId: AgentTypeId
  agentTypeKey: AgentTypePage_agentType$key | null
  cloudImagesKey: AgentTypePage_cloudImages$key | null
  parametersTabEntryPoint?: PreloadedEntryPoint<AgentTypeParametersComponentType>
}

function AgentTypePage({
  agentTypeId,
  agentTypeKey,
  cloudImagesKey,
  parametersTabEntryPoint,
}: Props) {
  const agentType = useFragment(agentTypeFragment, agentTypeKey)
  const cloudImages = useFragment(cloudImagesFragment, cloudImagesKey)
  const cloudProfile = cloudImages?.cloudImage?.[0]?.profile
  const cloudProfileError = cloudProfile?.error

  const tabParam = useQueryParam('tab')
  const tab = tabParam != null ? toTabId(tabParam) : OverviewCloudImageTabNamesEnum.SUMMARY
  const kind = useQueryParam('kind')
  const location = useLocation()
  const navigate = useNavigate()
  const tabParamsKey = getTabParamsKey({
    agentTypeId,
  })
  const {tabs} = restApi.endpoints.getTabs.useQuery(getTabsArg(tabParamsKey, true, false), {
    selectFromResult: ({data}) => ({tabs: data ?? emptyArray}),
  })
  const onSelect = React.useCallback(
    (selectedTab: string) => {
      navigate(
        getHrefWithQueryParams(location, null, () => ({
          tab: selectedTab,
        })),
        {preventScrollReset: true},
      )
    },
    [navigate, location],
  )

  return (
    <div className={styles.page}>
      <PageTitle>{agentType?.name}</PageTitle>
      {cloudProfileError?.message != null && (
        <CloudProfileError
          className={styles.error}
          projectId={cloudProfile?.project?.id}
          cloudProfileId={cloudProfile?.id}
          message={cloudProfileError.message}
          details={cloudProfileError.detailedMessage}
        />
      )}
      <Tabs
        autoCollapse={process.env.NODE_ENV !== 'test'}
        className={tabStyles.tabs}
        selected={tab}
        onSelect={onSelect}
        key={stringifyId(agentTypeId)}
      >
        {tabs.map(({id, title}) => {
          const tabId = ClassicUICloudImageTabNamesEnum[stringifyId(id)]
          const tabHref = `${getAgentTypeHref(agentTypeId)}?${objectToQuery({
            tab: stringifyId(tabId),
          })}`

          if (tabId === OverviewCloudImageTabNamesEnum.HISTORY) {
            return (
              <OverviewTab id={tabId} key={stringifyId(tabId)} title={title} href={tabHref}>
                <AgentHistory
                  agent={{
                    typeId: agentTypeId,
                  }}
                  withAgentPatternFilter
                />
              </OverviewTab>
            )
          }

          if (tabId === OverviewCloudImageTabNamesEnum.AGENT_PARAMETERS) {
            return (
              <OverviewTab id={tabId} key={stringifyId(tabId)} title={title} href={tabHref}>
                {parametersTabEntryPoint && (
                  <Suspense fallback={<Loader />}>
                    <EntryPointContainer entryPointReference={parametersTabEntryPoint} props={{}} />
                  </Suspense>
                )}
              </OverviewTab>
            )
          }

          return tabId != null && IFRAME_TABS.includes(tabId) ? (
            <OverviewTab isClassic id={tabId} key={tabId} title={title} href={tabHref}>
              <ClassicUITabAdapter agentTypeId={agentTypeId} tabId={id} title={title} kind={kind} />
            </OverviewTab>
          ) : null
        })}
      </Tabs>
    </div>
  )
}

type Params = {
  agentTypeId: string
}
type Queries = {main: AgentTypePageQuery}
export type NestedEntryPoints = {parametersTab?: typeof AgentTypeParametersEntryPoint}
export default function AgentTypePageContainer({
  queries,
  entryPoints,
}: EntryPointProps<Queries, NestedEntryPoints, {}, {}>) {
  const params = useParams<Params>()
  const agentTypeId = toAgentTypeId(params.agentTypeId ?? '')
  const data = usePreloadedQuery(query, queries.main)

  const location = useLocation()
  const {routeAvailabilityError} = restApi.endpoints.getRouteAvailability.useQueryState(
    location.pathname,
    {
      selectFromResult: result => ({
        routeAvailabilityError:
          result.data != null && result.data.statusCode !== HTTPCodesEnum.OK ? result.data : null,
      }),
    },
  )
  const error =
    routeAvailabilityError != null
      ? new HTTPError(
          getAvailabilityErrorMessage({error: routeAvailabilityError, agentTypeId}) ??
            routeAvailabilityError.message,
          routeAvailabilityError.statusCode,
        )
      : null

  if (!window.GLOBAL_ERROR_PAGE_DISABLED && error != null) {
    throw error
  }

  return (
    <AgentTypePage
      agentTypeKey={data.agentType ?? null}
      cloudImagesKey={data.cloudImages ?? null}
      key={params.agentTypeId}
      agentTypeId={agentTypeId}
      parametersTabEntryPoint={entryPoints.parametersTab}
    />
  )
}
export type AgentTypePageContainerComponent = typeof AgentTypePageContainer
