import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type * as React from 'react'

import styles from './Alert.module.css'

export enum AlertType {
  INFO = 'info',
  WARNING = 'warning',
  ERROR = 'exception',
}

type Props = {
  className?: string
  contentClassName?: string
  children: React.ReactNode
  type?: AlertType
}

function Alert({children, className, contentClassName, type = AlertType.INFO}: Props) {
  return (
    <div className={classNames(styles.container, styles[type], className)}>
      <SvgIcon className={styles.icon} icon={type} />
      <div className={contentClassName}>{children}</div>
    </div>
  )
}

export default Alert
